flow.typescript:
// D28 · Part 0~5 · 오늘의 흐름 전체: VAD 구간 → 볼륨 거르기 → 턴 판단 → 끼어들기 → 지연 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_flow.ts
//   한 통화를 가상 시계로 흘려 보내며 다섯 단계를 차례로 거치고 마지막에 숫자를 확인
//   (대체: Silero VAD·Smart Turn·실제 서비스 대신 합성 표시와 규칙, 서비스 TTFB는 고정값)
const FRAME = 0.032;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const r2 = (x: number): number => Math.round(x * 100) / 100;

function segments(flags: boolean[], stopSecs: number): [number, number][] {
  // 1단계 VAD: stop_secs 이상 조용해지면 말 구간을 닫는다
  const segs: [number, number][] = [];
  let start: number | null = null;
  let quiet = 0;
  flags.forEach((f, i) => {
    const t = i * FRAME;
    if (f) {
      if (start === null) start = t;
      quiet = 0;
    } else if (start !== null) {
      quiet += FRAME;
      if (quiet >= stopSecs) {
        segs.push([r2(start), r2(t + FRAME - quiet)]);
        start = null;
        quiet = 0;
      }
    }
  });
  if (start !== null) segs.push([r2(start), r2(flags.length * FRAME - quiet)]);
  return segs;
}

function loudEnough(volume: number, minVolume: number = 0.6): boolean {
  // 2단계 볼륨: 작은 소리(TV)는 말이 아니다
  return volume >= minVolume;
}

function spokenWords(reply: string, cut: number | null, wordSec: number = 0.4): string {
  // 4단계 끼어들기: 끊긴 시각까지 말한 단어만 기록
  const words = reply.split(" ");
  return (cut === null ? words : words.slice(0, Math.floor((cut + 1e-9) / wordSec))).join(" ");
}

const spans = [[0.3, 0.9], [1.4, 2.2]];
const flags = Array.from({ length: Math.floor(4 / FRAME) }, (_, i) => spans.some(([s, e]) => s <= i * FRAME && i * FRAME < e));
const segs = segments(flags, 0.6); // 쉼 0.5초 < 0.6초 → 한 구간
const userOk = loudEnough(0.77); // 2단계
const tvOk = loudEnough(0.43);
const complete = !["데요", "고"].some((e) => "내일 오후 세 시요".endsWith(e)); // 3단계: 끝난 말투 → 턴 종료
const latency = r2(Math.max(0.6, 0.35) + 0.42 + 0.21); // 5단계
const kept = spokenWords("내일 오후 세 시에 예약이 가능합니다", 1.5);
console.log(`VAD 구간 ${JSON.stringify(segs)} · 사용자 통과 ${userOk} · TV 통과 ${tvOk} · 끝난 말투 ${complete} · 기록 '${kept}' · 지연 ${latency}초`);
check(segs.length === 1 && userOk && !tvOk && complete && kept === "내일 오후 세" && latency === 1.23, "한 구간 · TV 무시 · 끝난 말투 · 3단어 기록 · 1.23초여야 해요.");

vad.typescript:
// D28 · Part 1 · VAD 손잡이: stop_secs · start_secs를 바꾸면 말이 몇 번으로 끊기나 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_vad.ts
//   32 ms 조각마다 '말/조용' 표시를 만들고, VAD 규칙(start_secs 이상 말해야 시작 · stop_secs 이상 조용해야 끝)으로 구간을 나눈다
//   (대체: Silero VAD 확률 대신 합성한 말/조용 표시)
const FRAME = 0.032;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Seg = [number, number];
const r2 = (x: number): number => Math.round(x * 100) / 100;

function makeFlags(segments: Seg[], total: number): boolean[] {
  // (시작, 끝) 초 구간 안이면 말(true), 아니면 조용(false)
  return Array.from({ length: Math.floor(total / FRAME) }, (_, i) => segments.some(([s, e]) => s <= i * FRAME && i * FRAME < e));
}

function vadSegments(flags: boolean[], stopSecs: number, startSecs: number = 0.2): Seg[] {
  // VAD 규칙으로 말 구간 목록을 만든다
  const segs: Seg[] = [];
  let start: number | null = null;
  let run = 0;
  let quiet = 0;
  flags.forEach((f, i) => {
    const t = i * FRAME;
    if (f) {
      run += FRAME;
      quiet = 0;
      if (start === null && run >= startSecs) start = t + FRAME - run; // 말이 start_secs 이상 이어졌을 때 '시작'
    } else if (start === null) {
      run = 0; // 짧은 소리(딸깍)는 버린다
    } else {
      quiet += FRAME;
      if (quiet >= stopSecs) {
        // stop_secs 이상 조용하면 '끝'
        segs.push([r2(start), r2(t + FRAME - quiet)]);
        start = null;
        run = 0;
        quiet = 0;
      }
    }
  });
  if (start !== null) segs.push([r2(start), r2(flags.length * FRAME - quiet)]);
  return segs;
}

// 말 "내일 오후" + 0.5초 쉼 + "세 시요", 그리고 3.2초에 0.08초짜리 딸깍 소리
const flags = makeFlags([[0.3, 0.9], [1.4, 2.2], [3.2, 3.28]], 4.2);
const result: Record<number, Seg[]> = {};
for (const stop of [0.2, 0.3, 0.6, 0.8]) {
  result[stop] = vadSegments(flags, stop);
  console.log(`stop_secs=${stop}: 말 구간 ${result[stop].length}개 ${JSON.stringify(result[stop])} · 말 끝 판정 지연 +${stop}초`);
}
const noFilter = vadSegments(flags, 0.6, 0);
console.log(`start_secs=0 이면 딸깍도 말: ${noFilter.length}개`);
check(result[0.2].length === 2 && result[0.3].length === 2 && result[0.6].length === 1 && result[0.8].length === 1 && noFilter.length === 2, "쉼(0.5초)보다 짧은 stop_secs는 말을 둘로 자르고, start_secs가 딸깍을 걸러야 해요.");

volume.typescript:
// D28 · Part 1 · min_volume · TV: 배경 TV 소리는 말로 치지 않기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_volume.ts   (소리는 코드 안에서 합성해요)
//   VAD가 '사람 말소리 같다'고 해도, 소리 크기가 min_volume보다 작으면 무시한다 (가까운 내 목소리 vs 멀리서 나는 TV)
//   (대체: Silero 확률 대신 합성 신호의 RMS를 dB → 0~1 크기로 바꿔 비교)
const SR = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function volume(y: Float32Array): number {
  // RMS를 dB로 바꾸고 -60 dB = 0, 0 dB = 1로 눌러 0~1 크기를 만든다
  let e = 0;
  for (const v of y) e += v * v;
  const db = 20 * Math.log10(Math.max(Math.sqrt(e / y.length), 1e-6));
  return Math.min(1, Math.max(0, (db + 60) / 60));
}

function accepted(y: Float32Array, minVolume: number): boolean {
  // 크기가 min_volume 이상일 때만 '말'로 받아들인다
  return volume(y) >= minVolume;
}

const user = new Float32Array(SR).map((_, i) => 0.2 * Math.sin((2 * Math.PI * 200 * i) / SR)); // 마이크 앞 사용자 (큰 소리)
const tv = new Float32Array(SR).map((_, i) => 0.02 * Math.sin((2 * Math.PI * 180 * i) / SR + 1)); // 방 건너편 TV (작은 소리)
console.log(`크기: 사용자 ${volume(user).toFixed(2)} · TV ${volume(tv).toFixed(2)}`);
const rows: Record<number, [boolean, boolean]> = {};
for (const mv of [0, 0.3, 0.6, 0.9]) {
  rows[mv] = [accepted(user, mv), accepted(tv, mv)];
  console.log(`min_volume=${mv}: 사용자 ${rows[mv][0] ? "통과" : "무시"} · TV ${rows[mv][1] ? "통과" : "무시"}`);
}
check(rows[0].join() === "true,true" && rows[0.6].join() === "true,false" && rows[0.9].join() === "false,false", "0.6이면 TV만 걸러지고, 너무 높이면(0.9) 사용자까지 무시돼요.");

turn.typescript:
// D28 · Part 2 · 턴 판단 두 가지: '조용하면 끝' vs '말을 듣고 판단' — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_turn.ts
//   Speech Timeout(조용함 0.6초면 끝)은 말 중간의 쉼에서 턴을 자르고, Smart Turn은 '끝난 말투'일 때만 끝낸다
//   (대체: Smart Turn 오디오 모델 대신 글자의 끝맺음을 보는 간단한 규칙)
const QUIET_END = 0.6;
const MAX_WAIT = 2.0;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Chunk = [string, number]; // [글자, 뒤에 이어진 쉼 초]

function looksComplete(text: string): boolean {
  // 문장이 끝난 말투인가? (대체 규칙: '-데요 · -고 · -서'처럼 이어지는 어미면 아직 안 끝남)
  return !["데요", "고", "서", "인데"].some((e) => text.trimEnd().endsWith(e));
}

function turnsBy(chunks: Chunk[], smart: boolean): string[] {
  // smart=false: 쉼이 0.6초 이상이면 무조건 턴 끝 · smart=true: '끝난 말투'가 아니면 MAX_WAIT까지 더 기다린다
  const turns: string[] = [];
  let cur = "";
  for (const [text, pause] of chunks) {
    cur = `${cur} ${text}`.trim();
    const wait = smart && !looksComplete(cur) ? MAX_WAIT : QUIET_END;
    if (pause >= wait) {
      turns.push(cur);
      cur = "";
    }
  }
  return cur ? [...turns, cur] : turns;
}

// "예약하고 싶은데요 (쉼 0.8초) 내일 오후 세 시요 (쉼 1.0초)"
const chunks: Chunk[] = [["예약하고 싶은데요", 0.8], ["내일 오후 세 시요", 1.0]];
const a = turnsBy(chunks, false);
const b = turnsBy(chunks, true);
console.log("Speech Timeout:", JSON.stringify(a), "→ 비서가 첫 조각만 듣고 끼어듦");
console.log("Smart Turn    :", JSON.stringify(b));
check(a.length === 2 && b.length === 1 && b[0] === "예약하고 싶은데요 내일 오후 세 시요" && looksComplete("내일 세 시요"), "Smart Turn은 '~는데요'에서 기다려 한 턴으로 묶어야 해요.");

barge.typescript:
// D28 · Part 3 · 끼어들기 타임라인: 사용자가 비서 말 도중에 말하면 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_barge.ts
//   비서는 0.4초에 한 단어씩 말한다. 사용자가 t초에 말을 시작하면 TTS를 끊고, 대화 기록에는 '실제로 말한 부분'만 남긴다
//   (대체: 실제 오디오 재생 대신 단어별 가상 시각)
const WORD_SEC = 0.4;
const REPLY = "내일 오후 세 시에 예약이 가능하고 비용은 오만 원입니다".split(" ");

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function spokenUntil(t: number | null): string[] {
  // t초에 끊겼을 때까지 끝까지 발음한 단어들 (null이면 끝까지)
  return t === null ? REPLY : REPLY.filter((_, i) => (i + 1) * WORD_SEC <= t + 1e-9);
}

function run(bargeAt: number | null, interruptionsEnabled: boolean = true): { stoppedAt: number | null; assistantContext: string; wastedWords: number } {
  // 사용자가 bargeAt초에 말을 시작한 통화 한 번을 흉내 낸다
  const cut = bargeAt !== null && interruptionsEnabled ? bargeAt : null;
  const words = spokenUntil(cut);
  return { stoppedAt: cut, assistantContext: words.join(" "), wastedWords: REPLY.length - words.length };
}

const full = run(null);
const cut = run(1.5);
const off = run(1.5, false);
console.log("끊기지 않음 :", JSON.stringify(full));
console.log("1.5초에 끼어듦:", JSON.stringify(cut));
console.log("끼어들기 끔 :", JSON.stringify(off));
check(cut.assistantContext === "내일 오후 세" && cut.stoppedAt === 1.5 && cut.wastedWords === 6 && off.assistantContext === full.assistantContext, "1.5초면 3단어(1.2초까지)만 말한 것으로 기록돼야 해요.");

mode.python:
# D28 · Part 3 · 끼어들기 설정: 허용 · 끔 · 첫 안내는 끝까지 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d28_mode.py   (Pipecat 없이 가상 시계로 · 인터넷·GPU·마이크 불필요)
#   비서 말: 첫 안내(0~2초) + 본문(2~5초). 설정 A(기본: 언제든 끊기) · B(끔) · C(첫 안내가 끝난 뒤에만 끊기)
#   (대체: Pipecat의 interruption 설정·전략 대신 설정 이름별 판정 함수)
FIRST_END, TOTAL = 2.0, 5.0


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def decide(mode: str, t: float) -> str:
    """사용자가 t초에 말을 시작했을 때 비서가 하는 일: 'stop'(끊고 듣기) · 'keep'(계속 말하기) · 'listen'(비서가 말 안 하는 중)."""
    if t >= TOTAL:
        return "listen"
    if mode == "A":
        return "stop"
    if mode == "B":
        return "keep"
    return "keep" if t < FIRST_END else "stop"         # C: 첫 안내(회사 이름·녹음 고지)는 끝까지


MODES = {"A": "끼어들기 허용", "B": "끼어들기 끔", "C": "첫 안내만 보호"}
table = {m: [decide(m, t) for t in (1.0, 3.0, 6.0)] for m in MODES}
print("사용자 말 시작 시각:    1.0초(첫 안내 중) · 3.0초(본문 중) · 6.0초(비서 말 끝난 뒤)")
for m, row in table.items():
    print(f"설정 {m} {MODES[m]:<8}: {row}")
check(table == {"A": ["stop", "stop", "listen"], "B": ["keep", "keep", "listen"], "C": ["keep", "stop", "listen"]},
      "C는 첫 안내 동안만 keep, 이후에는 stop이어야 해요.")

mode.typescript:
// D28 · Part 3 · 끼어들기 설정: 허용 · 끔 · 첫 안내는 끝까지 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_mode.ts
//   비서 말: 첫 안내(0~2초) + 본문(2~5초). 설정 A(기본: 언제든 끊기) · B(끔) · C(첫 안내가 끝난 뒤에만 끊기)
//   (대체: Pipecat의 interruption 설정·전략 대신 설정 이름별 판정 함수)
const FIRST_END = 2.0;
const TOTAL = 5.0;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function decide(mode: string, t: number): string {
  // 사용자가 t초에 말을 시작했을 때 비서가 하는 일: stop(끊고 듣기) · keep(계속 말하기) · listen(비서가 말 안 하는 중)
  if (t >= TOTAL) return "listen";
  if (mode === "A") return "stop";
  if (mode === "B") return "keep";
  return t < FIRST_END ? "keep" : "stop"; // C: 첫 안내(회사 이름·녹음 고지)는 끝까지
}

const MODES: Record<string, string> = { A: "끼어들기 허용", B: "끼어들기 끔", C: "첫 안내만 보호" };
const table: Record<string, string[]> = {};
for (const m of Object.keys(MODES)) table[m] = [1.0, 3.0, 6.0].map((t) => decide(m, t));
console.log("사용자 말 시작 시각:    1.0초(첫 안내 중) · 3.0초(본문 중) · 6.0초(비서 말 끝난 뒤)");
for (const [m, row] of Object.entries(table)) console.log(`설정 ${m} ${MODES[m].padEnd(8)}: ${row.join(", ")}`);
check(table.A.join() === "stop,stop,listen" && table.B.join() === "keep,keep,listen" && table.C.join() === "keep,stop,listen", "C는 첫 안내 동안만 keep, 이후에는 stop이어야 해요.");

metrics.typescript:
// D28 · Part 4 · 지연 분해: '말 끝 → 첫 소리'를 서비스별 TTFB로 나눠 재기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_metrics.ts
//   서비스마다 '요청 → 첫 결과'(TTFB)를 Observer가 모으고, 턴 끝 판단 대기와 합쳐 사용자가 느끼는 지연을 만든다
//   (대체: 실제 STT·LLM·TTS 대신 고정 TTFB 0.35 · 0.42 · 0.21초, 시간은 가상 시각)
const STOP_SECS = 0.6;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class MetricsObserver {
  // 파이프라인을 바꾸지 않고 서비스별 TTFB를 모은다
  ttfb: Record<string, number> = {};
  onTtfb(service: string, seconds: number): void {
    this.ttfb[service] = seconds;
  }
}

function oneTurn(speechEnd: number, obs: MetricsObserver): number {
  // 말 끝 시각부터 첫 소리가 나는 시각까지 한 턴을 가상 시계로 돌리고 지연(초)을 돌려준다
  const [stt, llm, tts] = [0.35, 0.42, 0.21];
  obs.onTtfb("stt", stt);
  obs.onTtfb("llm", llm);
  obs.onTtfb("tts", tts);
  const turnEnd = Math.max(speechEnd + STOP_SECS, speechEnd + stt); // 조용함 0.6초와 받아쓰기 도착 중 늦은 쪽
  return Math.round((turnEnd + llm + tts - speechEnd) * 100) / 100;
}

const obs = new MetricsObserver();
const latency = oneTurn(10.0, obs);
const entries = Object.entries(obs.ttfb);
const slowest = entries.reduce((a, b) => (b[1] > a[1] ? b : a))[0];
const sum = entries.reduce((s, [, v]) => s + v, 0);
for (const [name, v] of entries) console.log(`${name.padEnd(4)} TTFB ${v.toFixed(2)}초`);
console.log(`말 끝 → 첫 소리 ${latency}초 (서비스 TTFB 합 ${sum.toFixed(2)}초 + 턴 판단 대기 겹침분)`);
check(latency === 1.23 && slowest === "llm" && Math.round(sum * 100) / 100 === 0.98, "0.6초 대기 + LLM 0.42 + TTS 0.21 = 1.23초, 가장 느린 서비스는 llm이에요.");

