// D28 · Part 4 · 지연 예산: 목표 '말 끝 → 첫 소리 p50 1.0초 이하'를 맞추려면 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d28_budget.ts
//   20턴의 지연을 난수로 만들어 p50(중앙값)을 구하고, stop_secs를 0.6 → 0.3으로 줄였을 때 예산을 맞추는지 본다
//   (대체: 실제 통화 기록 대신 항상 같은 순서로 나오는 난수 · 서비스 지연 범위는 가정값)
const TARGET = 1.0;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function lcg(seed: number): () => number {
  // 항상 같은 0~1 난수열
  let s = seed;
  return () => {
    s = (Math.imul(s, 1103515245) + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
}

function latencies(stopSecs: number, n: number = 20, seed: number = 11): number[] {
  // 턴마다: 턴 대기 = max(stop_secs, STT) → + LLM 첫 글자 + TTS 첫 소리
  const r = lcg(seed);
  const out: number[] = [];
  for (let i = 0; i < n; i++) {
    const stt = 0.25 + 0.2 * r();
    const llm = 0.25 + 0.3 * r();
    const tts = 0.1 + 0.1 * r();
    out.push(Math.max(stopSecs, stt) + llm + tts);
  }
  return out;
}

function median(xs: number[]): number {
  const a = [...xs].sort((x, y) => x - y);
  const m = a.length >> 1;
  return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
}

const p50b = median(latencies(0.6));
const p50a = median(latencies(0.3));
console.log(`stop_secs 0.6 → p50 ${p50b.toFixed(2)}초 (${p50b > TARGET ? "예산 초과" : "예산 이내"})`);
console.log(`stop_secs 0.3 → p50 ${p50a.toFixed(2)}초 (${p50a > TARGET ? "예산 초과" : "예산 이내"})  · 대신 쉼에서 말이 끊길 위험(D28 vad 참고)`);
check(p50b > TARGET && TARGET >= p50a, "stop_secs를 줄이면 p50이 1.0초 아래로 내려와야 해요.");

