# D28 · Part 5 · 오늘 정리: VAD · 턴 · 끼어들기 · 지연 네 가지를 숫자 하나씩으로 확인 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d28_recap.py   (Pipecat 없이 · 인터넷·GPU·마이크 불필요)
#   쉼 0.5초가 있는 말 · 끼어들기 1.5초 · 서비스 지연을 넣고 오늘의 핵심 숫자를 표로 만든다
#   (대체: 노트북의 SUMMARY 표 대신 같은 의미의 가상 값)


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def turns_for(pauses: list[float], stop_secs: float) -> int:
    """말 중간 쉼 목록에서 stop_secs 이상인 쉼마다 턴이 하나 더 생긴다."""
    return 1 + sum(1 for p in pauses if p >= stop_secs)


def words_before(cut: float, word_sec: float = 0.4) -> int:
    """cut초에 끊기면 끝까지 말한 단어 수."""
    return int((cut + 1e-9) // word_sec)


def user_bot_latency(stop_secs: float, stt: float, llm: float, tts: float) -> float:
    """말 끝 → 첫 소리 = max(턴 대기, STT) + LLM + TTS."""
    return round(max(stop_secs, stt) + llm + tts, 2)


summary = {
    "stop_secs 0.3, 쉼 0.5초 → 턴 수": turns_for([0.5], 0.3),
    "stop_secs 0.6, 쉼 0.5초 → 턴 수": turns_for([0.5], 0.6),
    "1.5초에 끼어들면 기록에 남는 단어 수": words_before(1.5),
    "말 끝 → 첫 소리(초)": user_bot_latency(0.6, 0.35, 0.42, 0.21),
    "stop_secs 0.3으로 줄이면(초)": user_bot_latency(0.3, 0.35, 0.42, 0.21),
}
for k, v in summary.items():
    print(f"{k}: {v}")
check(list(summary.values()) == [2, 1, 3, 1.23, 0.98], "쉼이 stop_secs보다 길면 턴이 갈라지고, 지연은 max(대기, STT)+LLM+TTS예요.")

